class Solution { public:
 int minGroupsForValidAssignment(vector<int>& nums){
  unordered_map<int,int> cnt;for(int x:nums)++cnt[x];int mn=INT_MAX;for(auto p:cnt)mn=min(mn,p.second);
  for(int g=mn;g>=1;--g){int groups=0;bool ok=true;
   for(auto p:cnt){int f=p.second,need=(f+g)/(g+1);
    if(need>f/g){ok=false;break;}groups+=need;}
   if(ok)return groups;
  }return nums.size();
 }
};
